using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.Blueprint.D5.S3.Geometry.Polygons.PolygonConditionalCountsFormula;
namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Polygons;
internal sealed class PolygonConditionalCountsDocument : IScribeDocumentDefinition
{
    private static DocumentBlock Node(string name, string title, Formula statement, string prose,
        DescribeRole role = DescribeRole.Theorem) => Describe.Lean(
        DescribeId.Create("polygon-conditional-counts-" + name.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/Geometry/Polygons/PolygonConditionalCounts." + name),
        H(title), StatementSource.FromAuthor(Disp(statement)), AssessedProvenance.FromRepo(),
        Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Catalan counts of complete conditioned polygon fibres", H("Actual original chord sets"), Blocks(
        Paragraph(Text("V(n) means ZMod(n); H(n,P) is the subtype of every finite original chord set T satisfying Carrier.IsTriangulation T and P subset EarCenters(T). Triangulation includes internal-diagonal validity, pairwise noncrossing and full maximality. Compatible(P) means that distinct ears with centres in P do not cross. ConditionFiber is the existing complete original-carrier subtype, including its trace constraint; with both trace arguments empty that constraint is automatic. No completion is selected or quotient taken.")),
        Node("forced_card", "All completions containing compatible forced ears", Forced(),
            "The actual iterated deletion equivalence forcedEquiv identifies H(n,P) with every triangulation of the (n-card(P))-gon. The licensed supplier encard_setOf_isTriangulation is applied through the identity on whole chord sets; both carrier inverses are reflexive equalities. Its catalanNumber is definitionally the receiver's Mathlib catalan. This is the containing-event count in B-32, formula (32.1)."),
        Node("Npq", "Integer alternating Catalan sum", Definition(),
            "Npq has values in the integers. All subtractions inside the Catalan index are natural subtraction; choose and catalan are cast to the integers before multiplication. This total definition does not assert any geometric existence or positivity.", DescribeRole.Definition),
        Node("conditional_card", "Every completion with forced P and forbidden Q", Conditional(),
            "For arbitrary disjoint P,Q with compatible union, Mathlib Finset.inclusion_exclusion_card_inf_compl counts the complement of the forbidden-ear events inside the complete forced-P carrier. Every event intersection is equivalent to the complete forced-(P union S) carrier, S subset Q. The term is Catalan(n-card(P)-card(S)-2). Mathlib Finset.sum_powerset_apply_card groups these terms by card(S), giving the binomial coefficient. This proves the cardinality part of (37.3), without its positivity assertion."),
        Paragraph(Text("The source is AURIC_FIB_ATOM_INTRINSIC_CLASSIFICATION_AND_POLYGON_GEOMETRY, B-32 and B-37.2, at revision 4b62d1ff02a702a51332eae3324db7daac400cd5. Its four parameter cases (p,q)=(2,2),(3,3),(2,4),(4,2) are instances of the same theorem at every permitted cyclic placement. Interchanging P,Q is another application with disjointness reversed and union commuted; it uses Nqp, without identifying the weights.")),
        Paragraph(Text("The compatible-card bound gives 2 card(P union Q) <= n. For each j <= card(Q), disjointness gives card(P)+j <= floor(n/2), so n-card(P)-j >= ceil(n/2) >= 7. Thus the displayed Catalan indices are legal ordinary indices; natural truncation in the total definition is inactive on the source domain.")),
        Paragraph(Text("Formula (37.6) follows from this same theorem applied to P union I and Q when I subset E_K(P union Q) and Compatible(I). Membership in E_K supplies disjointness from P union Q and compatibility with every one of its ears. Together with the two internal compatibility assumptions, these facts give compatibility of P union I union Q; card(P union I)=card(P)+card(I). Its ConditionFiber is exactly the original complete carrier with P and I forced and Q forbidden. Every nonzero term has the same legal-index bound using this larger union.")),
        Paragraph(Text("Positivity of Npq, the general exact-trace formula (37.7), strict flip inequalities, normalized inequality (37.4), and its equality classification require their own arguments. Catalan enumeration and finite inclusion-exclusion supply the counts below.")),
        Paragraph(Text("For the twenty-gon take U=ZMod(20), and let C20 have adjacency y=x+1 or x=y+1. Let D be any six-element subset of a single parity class, P any two-element subset of D, and J any cyclically independent subset of U outside D and every neighbour of P. Set A=D minus P and R=A union J. J may be empty, nonmaximal or in the same parity class as D. Count O using every original maximal noncrossing internal chord set T with EarCenters(T) intersect D=P and EarCenters(T) disjoint J. There is no restriction on its other ears, no selected completion, and no change of polygon. This is the count and graph correspondence underlying B44.2, formula (44.3), of AURIC_FIB_ATOM_POLYGON_TWENTY_GON_SAME_PARITY_DEFICIT.")),
        Paragraph(Text("This condition on the same T is equivalent to forcing P and forbidding R. In the finite carrier of all triangulations forcing P, use the ear-membership event at each vertex of R. Finset.inclusion_exclusion_card_inf_compl gives the sum over every I subset R with sign (-1)^card(I). The original event-intersection equivalence preserves the entire chord set T and identifies its carrier with all triangulations forcing P union I. P is disjoint from R and has no adjacency to R. Hence P union I is independent exactly when I is independent in C20. If I is not independent, PolygonCompressionTrace.earCenters_independent makes this forcing carrier empty, so its term is zero. No containing-event Catalan formula is applied to such a union.")),
        Paragraph(Text("For independent I, PolygonCompressionTrace.independent_iff_noncrossing gives compatibility of P union I. Apply forced_card at n=20 to this union. Its size is 2+card(I), so the count is Catalan(16-card(I)); the sign still uses card(I). Filtering away the empty forcing carriers gives O, cast to the integers, equal to PathCatalanFunctional.phi(C20,R,16). No binomial coefficient replaces the actual independent-subset multiplicities. At I empty the term is Catalan(16). Compatibility bounds card(I) by eight in every nonzero term, giving a reduced polygon of at least ten vertices and a Catalan index of at least eight.")),
        Paragraph(Text("The original graph G is C20 induced on the subtype of all x in R. Map each finite subset of this subtype to its image under subtype.val; the inverse takes the subtype of a subset of R. These maps preserve cardinality and independence, so phi(C20,R,16)=phi(G,univ,16). They preserve every vertex identity and every isolate, including the empty independent configuration. A and J give disjoint covering independent parts of this actual graph; the A part has four vertices and the J part has card(J) vertices.")),
        Paragraph(Text("Choose p in P. For x in R, the representative (x-p).val is nonzero. Sending x to that natural number is injective and takes every actual edge to consecutive natural numbers: the only possible wrap would pass through the excluded p. Thus G maps injectively to the natural-number Hasse path and is acyclic by SimpleGraph.IsAcyclic.comap. Its image may be disconnected and need not be an interval. Every neighbour of x still has original label x-1 or x+1, so every actual vertex has degree at most two.")),
        Paragraph(Text("P union J is independent and has size 2+card(J), so compatible_card_bound first gives card(J)<=8. Equality would make it a half-density independent subset of C20. To see the rigidity, translate P union J by one. The two disjoint sets have ten vertices each and therefore cover U, so membership alternates at each step. This gives a period-two membership predicate on natural representatives; Function.Periodic.map_mod_nat reduces it to the remainder modulo two. Applying it with a vertex of P puts every vertex of D into P union J. Since J avoids D this gives D subset P, contradicting their sizes six and two. Therefore card(J)<=7 without a maximality assumption. The actual graph has 4+card(J)<=11 vertices, and even the formal indices of the zero terms satisfy 16-card(I)>=5 for I subset R.")),
        Paragraph(Text("Write Phi_m(K) for PathCatalanFunctional.phi(K,univ,m). Keep the same U,D,P,J,A,R and the full original graph G above; writing N(P) for all neighbours of P in C20, the condition on J is precisely J subset univ minus (D union N(P)), together with independence. Set r=7-card(J). For each 0<=q<=r, form Hq from G disjoint_union the edgeless graph on natural labels, induced on every inl(x) for x in the actual subtype R and every inr(k) for k<q. The left tags retain every original label, edge and isolate. The right tags are new graph comparison vertices; the polygon still has twenty vertices.")),
        Paragraph(Text("The tagged copies of A and of J together with the q right tags are disjoint independent parts covering all of Hq. Their sizes are four and card(J)+q, so card(Hq)=4+card(J)+q<=11 and Hr has parts (4,7). The forest_path_order construction in "), Ref("D5/S3/Combinatorics/Graph/LinearForests/FiniteForestCatalan"), Text(" orders the whole original forest along a path, including its disconnected components and isolates. Place the new isolated tags after that order. This gives an injective graph map to the natural-number Hasse path, so SimpleGraph.IsAcyclic.comap gives acyclicity of every Hq. Old degrees are unchanged and new degrees are zero; hence every actual degree is at most two. The same module's phi_map and phi_subtype identify the functional on these tagged induced carriers, in particular Phi_16(H0)=Phi_16(G).")),
        Paragraph(Text("For q<r, apply "), Ref("D5/S3/StatisticalMechanics/HardCore/IndependentPartitionDeletion.partition_delete"), Text(" to the new isolated vertex inr(q) of H(q+1), with every vertex weight equal to -X in integer power series. Deleting that vertex and deleting its closed neighbourhood both leave Hq. Thus its independent-set partition series gains the factor 1-X. Multiply by the integer Catalan series and take coefficient sixteen. FiniteForestCatalan.coeff_partition_phi identifies these coefficients with the corresponding Phi values; its size hypotheses hold because card(H(q+1))<=11<=16 and card(Hq)<=11<=15. The exact step is Phi_16(Hq)-Phi_16(H(q+1))=Phi_15(Hq).")),
        Paragraph(Text("Summing these steps gives Phi_16(G)-Phi_16(Hr)=sum(q<r) Phi_15(Hq). Every summand concerns the current padded graph Hq, with parameter fifteen fixed throughout. Apply "), Ref("D5/S3/Combinatorics/Graph/LinearForests/FiniteForestCatalan.finite_forest_phi_nonnegative"), Text(" to each actual Hq, using acyclicity, degree at most two and 15>=card(Hq). All summands are nonnegative, and therefore Phi_16(Hr)<=Phi_16(G)=O for every original permitted D,P,J. This includes empty and nonmaximal J and every original isolate. If card(J)=7, then r=0, the sum is empty and the comparison is equality.")),
        Paragraph(Text("A further independent bound Phi_16(Hr)>=29205 is required at the fixed actual covering parts (4,7). A proposed structural route is Phi_16(Hr)>=Phi_16(P9 disjoint_union 2K1), followed by evaluation of the right-hand side. The comparison must respect the fixed parts and the actual isolates. Isolate padding and universal forest nonnegativity supply the padding comparison, but do not establish this extremal bound or the numeric target 29205. The original same-family deficit bound 69320276, the actual C0 case and the native operation, readout, continuation and resource correspondences remain separate questions."))
        ), []));
    private static Formula Forced() => Scope(All("P", Sets, Imp(Lower,
        Imp(C("Compatible", X("P")), Eq(C("Natcard", C("H", X("n"), X("P"))),
            Cat(Sub(Sub(X("n"), Card(X("P"))), N(2))))))));
    private static Formula Definition() => All("n", X("Nat"), All("p", X("Nat"), All("q", X("Nat"),
        Eq(C("Npq", X("n"), X("p"), X("q")),
            SumOver("j", C("range", AddF(X("q"), N(1))),
                Mul(Mul(Pow(Sub(N(0), N(1)), X("j")), AsInt(C("choose", X("q"), X("j")))),
                    AsInt(Cat(Sub(Sub(Sub(X("n"), X("p")), X("j")), N(2))))))))));
    private static Formula Conditional() => Scope(All("P", Sets, All("Q", Sets,
        Imp(Lower, Imp(C("Disjoint", X("P"), X("Q")),
            Imp(C("Compatible", C("union", X("P"), X("Q"))),
                Eq(AsInt(C("Natcard", C("ConditionFiber", X("P"), X("Q"), C("empty"), C("empty")))),
                    C("Npq", X("n"), Card(X("P")), Card(X("Q"))))))))));
}
internal static class PolygonConditionalCountsFormula
{
    internal static Formula X(string n) => F.Id(n);
    internal static Formula N(int n) => n == 14 ? D(1,4) : D((byte)n);
    internal static Formula C(string n, params Formula[] args) => new Formula.Apply(Seq(Operatorname, Grp(X(n))), [.. args]);
    internal static Formula All(string n, Formula type, Formula body) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(n), type, body);
    private static Formula Operand(Formula f) => f is Formula.Bind ? Seq(Open,f,Close) : f;
    internal static Formula R(Formula a, Formula op, Formula b) => Seq(Open, Operand(a), Sp, op, Sp, Operand(b), Close);
    internal static Formula Eq(Formula a, Formula b) => R(a, F.Eq, b);
    internal static Formula Imp(Formula a, Formula b) => R(a, Implies, b);
    internal static Formula AddF(Formula a, Formula b) => R(a, Plus, b);
    internal static Formula Sub(Formula a, Formula b) => R(a, Minus, b);
    internal static Formula Mul(Formula a, Formula b) => R(a, Cdot, b);
    internal static Formula Pow(Formula a, Formula b) => new Formula.Power(a,b);
    internal static Formula AsInt(Formula a) => Seq(Open,a,Colon,Sp,new Formula.Integers(),Close);
    internal static Formula Cat(Formula a) => C("catalan", a);
    internal static Formula Card(Formula a) => C("card", a);
    internal static Formula Sets => C("Finset", C("ZMod", X("n")));
    internal static Formula Lower => R(N(14), Leq, X("n"));
    internal static Formula Scope(Formula body) => All("n", X("Nat"), Seq(OpenBracket,C("NeZero",X("n")),CloseBracket,Comma,Sp,body));
    internal static Formula SumOver(string v, Formula domain, Formula body) => Seq(Sum,Sp,Underscore,Grp(X(v),InMacro,Sp,domain),Sp,Open,body,Close);
}
